import { canonicalSha256 } from '../core/canonical-json.mjs';
import { omissionEntry, finalizeOmissionManifest } from './omission-manifest.mjs';
const TIER_PRIORITY={L0:400,L1:300,L2:200,L3:100};
export class TieredMemoryManager{
 constructor({tokenRegistry,model}){if(!tokenRegistry)throw new TypeError('tokenRegistry is required');this.registry=tokenRegistry;this.model=model;this.entries=[];}
 add(entry){if(!entry?.id||!TIER_PRIORITY[entry.tier]||!entry.text)throw new TypeError('Memory entry requires id, tier, and text');if((entry.sourceIds??[]).length!==(entry.sourceHashes??[]).length)throw new TypeError('Memory source IDs and hashes must align');const record=Object.freeze({...entry,sourceIds:[...(entry.sourceIds??[])],sourceHashes:[...(entry.sourceHashes??[])],sha256:canonicalSha256({id:entry.id,tier:entry.tier,text:entry.text,sourceIds:entry.sourceIds??[],sourceHashes:entry.sourceHashes??[],validUntil:entry.validUntil??null})});this.entries.push(record);return record;}
 async select({budgetTokens,sourceState={},now=new Date()}){const candidates=[];const omissions=[];for(const entry of this.entries){const expired=entry.validUntil&&Date.parse(entry.validUntil)<=now.getTime();const stale=(entry.sourceIds??[]).some((id,index)=>sourceState[id]!==entry.sourceHashes[index]);if(expired||stale){omissions.push(omissionEntry({sourceId:entry.id,category:'memory',reason:expired?'expired memory summary':'stale memory source hash',sourceHash:entry.sha256}));continue;}const tokens=await this.registry.countText(this.model,entry.text);candidates.push({...entry,tokens,priority:TIER_PRIORITY[entry.tier]});}candidates.sort((a,b)=>b.priority-a.priority||a.id.localeCompare(b.id));let used=0;const selected=[];for(const item of candidates){if(used+item.tokens<=budgetTokens){selected.push(Object.freeze(item));used+=item.tokens;}else omissions.push(omissionEntry({sourceId:item.id,category:'memory',reason:`memory budget ${budgetTokens} exceeded`,estimatedTokens:item.tokens,sourceHash:item.sha256}));}const manifest=finalizeOmissionManifest(omissions);return Object.freeze({entries:Object.freeze(selected),usedTokens:used,budgetTokens,omissions:manifest.entries,omissionManifestSha256:manifest.sha256});}
}
